import java.io.*;
import java.util.*;

public class Main {
    long mod = 1_000_000_007;

    long inv(long n) {
        long k = mod - 2;
        long res = 1;
        long a = n;
        while(k > 0) {
            if ((k & 1) > 0) {
                res = (res * a) % mod;
            }
            a = (a * a) % mod;
            k >>= 1;
        }
        return res;
    }

    public void solve() {
        long[] f = new long[51];
        f[0] = 1;
        for (int i = 1; i < 51; i++) {
            f[i] = (f[i - 1] * i) % mod;
        }
        long[][] c = new long[51][51];
        for (int i = 0; i < 51; i++) {
            c[i][0] = 1;
        }
        for (int i = 1; i < 51; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (f[i] * inv(((f[j] * f[i - j]) % mod))) % mod;
            }
        }

        int n = ni();
        int k = ni();
        int c50 = 0, c100 = 0;
        for (int i = 0; i < n; i++) {
            if (ni() == 100) c100++;
            else c50++;
        }
        Node[][][] ns = new Node[c50 + 1][c100 + 1][2];
        for (int i = 0; i <= c50; i++) {
            for (int j = 0; j <= c100; j++) {
                ns[i][j][0] = new Node(i, j, 0);
                ns[i][j][1] = new Node(i, j, 1);
            }
        }
        for (int i = 0; i <= c50; i++) {
            for (int j = 0; j <= c100; j++) {
                int p50c = Math.min(k / 50, i);
                int p100c = Math.min(k / 100, j);
                for (int x = p100c; x >= 0; x--) {
                    for (int y = Math.min(p50c, (k - 100 * x) / 50); y >= 0; y--) {
                        if ( 0 == y && 0 == x) continue;
                        ns[i][j][0].s.add(ns[i - y][j - x][1]);
                        ns[i - y][j - x][1].s.add(ns[i][j][0]);
//                        System.out.println("(" + i + ", " + j + ", 0) -> (" + (i - y) + ", " + (j - x) + ", 1)");
//                        System.out.println("(" + (i - y) + ", " + (j - x) + ", 1) -> (" + i + ", " + j + ", 0)");
                    }
                }
            }
        }
        ArrayDeque<Node> q = new ArrayDeque<>();
        ns[c50][c100][0].n = 1;
        ns[c50][c100][0].am = 1;
        q.add(ns[c50][c100][0]);
        while (!q.isEmpty()) {
            Node cur = q.pop();
            for (Node  ch: cur.s) {
                if (ch.n == 0 || ch.n == cur.n + 1) {
                    long p1 = c[cur.b == 0 ? cur.c50 : c50 - cur.c50][Math.abs(cur.c50 - ch.c50)];
                    long p2 = c[cur.b == 0 ? cur.c100 : c100 - cur.c100][Math.abs(cur.c100 - ch.c100)];
                    ch.am = (ch.am + (cur.am * (p1 * p2) % mod) % mod) % mod;
                    if (ch.n == 0) {
                        ch.n = cur.n + 1;
                        q.add(ch);
                    }
//                    System.out.println("p1: " + p1 + ", i: " + (cur.b == 0 ? cur.c50 : c50 - cur.c50) + ", j:" +
//                            (Math.abs(cur.c50 - ch.c50)));
//                    System.out.println("(" + cur.c50 + ", " + cur.c100 + ", " + cur.b + ", " + cur.am + ") --> (" +
//                            + ch.c50 + ", " + ch.c100 + ", " + ch.b + ", " + ch.am + ")");
                }
            }
        }
        write(ns[0][0][1].n - 1 + "\n" + ns[0][0][1].am + "\n");
    }

    class Node {
        public int c50, c100, b, n;
        long am;
        public ArrayList<Node> s;
        public Node(int x, int y, int z) {
            c50 = x;
            c100 = y;
            b = z;
            s = new ArrayList<>();
            n = 0;
            am = 0;
        }
    }



    public static void main(String[] args) {
        Main m = new Main();
        m.solve();
        try {
            m.out.close();
        } catch (IOException e) {}
    }

    BufferedReader in;
    BufferedWriter out;
    StringTokenizer tokenizer;
    public Main() {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new BufferedWriter(new OutputStreamWriter(System.out));
    }
    public String n() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(in.readLine());
            } catch (IOException e) {}
        }
        return tokenizer.nextToken();
    }
    public int ni() {
        return Integer.parseInt(n());
    }
    public long nl() {
        return Long.parseLong(n());
    }
    public void write(String s) {
        try {
            out.write(s);
        } catch (IOException e) {}
    }
}
